{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill would let a public charter school authorized by the commission and the local board of education where the school is located agree in writing, within 30 calendar days of authorization, to make that board the school’s authorizer and local education agency. The board would assume the rights and responsibilities of the charter agreement, which must be filed with the commission as the commission directs. This option would not apply to a school whose charter agreement the commission renewed on appeal.",
      "rationale": "Conveys the eligible parties, written agreement, deadline, transfer of authority and responsibilities, and exception for commission renewals on appeal."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "the charter agreement, which must be filed with the commission as the commission directs.",
      "rationale": "States both the filing requirement and the commission's authority to prescribe its manner."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The bill would also change “A charter agreement” to “An initial charter agreement” in Section 49-13-110(b)(1)",
      "rationale": "Identifies the amended provision and the exact wording change."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "A renewed charter agreement approved by a local board would last 10 academic years.",
      "rationale": "Conveys the required 10-academic-year term for local-board-approved renewals."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "One approved by the commission would last between five and 10 academic years, as set by commission resolution.",
      "rationale": "Conveys the commission-approved renewal term range and determination by commission resolution."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "remove specified “notwithstanding” language from Sections 49-13-121(f)(3) and (l).",
      "rationale": "Identifies both amendment targets and the removal of notwithstanding language, but does not identify the provisions whose override is removed or the replacement with “If.”"
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "It would take effect upon becoming law.",
      "rationale": "States the effective-date trigger."
    }
  ]
}
